root.render(
  <React.StrictMode>
    <Auth0Provider>
      domain="dev-n3m8z2s3le8ld0ta.us.auth0.com"
      clientId="dqzucPjmiVKKiRO2Msw3ps8SUE1APTEL"
      redirectUri={window.location.origin}
      <App />
     </Auth0Provider>
  </React.StrictMode>
);
